import SwiftUI
struct DocumentationHomeView: View { var body: some View { List { NavigationLink("Skilled nursing visit note") { SNVisitNoteEditor() }; NavigationLink("Kaiser Initial Get Auth") { Text("Initial authorization form will be completed in phase 5.") }; NavigationLink("Kaiser Subsequent Authorization") { Text("Subsequent authorization form will be completed in phase 5.") } }.navigationTitle("Documentation") } }
struct SNVisitNoteEditor: View { @State private var reason = ""; @State private var status = ""; var body: some View { Form { ClinicalSection(title: "Reason for visit") { TextEditor(text: $reason).frame(minHeight: 80) }; ClinicalSection(title: "Current clinical status") { TextEditor(text: $status).frame(minHeight: 100) }; ClinicalSection(title: "Disclaimer") { Text("Documentation helper supports charting only and does not determine coverage or replace agency policy.") } }.navigationTitle("SN Visit Note") } }
